from typing import List

def maxSum(nums: List[int], m: int, k: int) -> int:
    if not nums or len(nums) < k:
        return 0

    current_sum = sum(nums[:k])
    counts = {}
    distinct_count = 0

    for i in range(k):
        val = nums[i]
        if val not in counts or counts[val] == 0:
            distinct_count += 1
            counts[val] = 1
        else:
            counts[val] += 1

    max_s = 0
    if distinct_count >= m:
        max_s = current_sum

    for i in range(k, len(nums)):
        # Remove the element that is sliding out of the window
        out_val = nums[i - k]
        counts[out_val] -= 1
        if counts[out_val] == 0:
            distinct_count -= 1

        # Add the new element entering the window
        in_val = nums[i]
        if in_val not in counts or counts[in_val] == 0:
            distinct_count += 1
            counts[in_val] = 1
        else:
            counts[in_val] += 1

        current_sum = current_sum - out_val + in_val

        if distinct_count >= m:
            if current_sum > max_s:
                max_s = current_sum

    return max_s
