from typing import List

def numberOfRightTriangles(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    row_counts = [0] * rows
    col_counts = [0] * cols

    for r in range(rows):
        for c in range(cols):
            if grid[r][c]:
                row_counts[r] += 1
                col_counts[c] += 1

    ans = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c]:
                # The current cell is the vertex of the right angle.
                # Number of triangles with this cell as the corner:
                # (Number of other 1s in row r) * (Number of other 1s in col c)
                ans += (row_counts[r] - 1) * (col_counts[c] - 1)
    return ans
