def punishmentNumber(n: int) -> int:
    def can_partition(s: str, target: int) -> bool:
        if not s:
            return target == 0

        for i in range(1, len(s) + 1):
            left = int(s[:i])
            if left > target:
                break
            if can_partition(s[i:], target - left):
                return True
        return False

    total_sum = 0
    for i in range(1, n + 1):
        square_str = str(i * i)
        if can_partition(square_str, i):
            total_sum += i * i

    return total_sum
